// src/lib/mcp/tools/list-projects.ts
var list_projects_default = defineTool({
  name: "list_projects",
  title: "List projects",
  description: "List The Anoma Company portfolio projects, optionally filtered by category (Solutions, Branding, Video Production, AI Video Production).",
  inputSchema: {
    filterTag: z.enum(["Solutions", "Branding", "Video Production", "AI Video Production"]).optional().describe("Optional category filter.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ filterTag }) => {
    const items = projects.filter((p) => !filterTag || p.filterTag === filterTag).map((p) => ({
      slug: p.slug,
      title: p.title,
      client: p.client,
      year: p.year,
      category: p.category,
      filterTag: p.filterTag,
      summary: p.summary,
      url: `https://theanoma.company/work/${p.slug}`
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(items, null, 2) }],
      structuredContent: { count: items.length, projects: items }
    };
  }
});

// src/lib/mcp/tools/get-project.ts
import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.26.2";
import { z as z2 } from "npm:zod@^3.25.76";
var get_project_default = defineTool2({
  name: "get_project",
  title: "Get project",
  description: "Get the full case-study details for one portfolio project by slug.",
  inputSchema: { slug: z2.string().trim().min(1).describe("Project slug, e.g. 'ai-chatbot'.") },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ slug }) => {
    const project = projects.find((p) => p.slug === slug);
    if (!project) {
      return {
        content: [
          {
            type: "text",
            text: `No project with slug "${slug}". Use list_projects to see available slugs.`
          }
        ],
        isError: true
      };
    }
    const payload = { ...project, url: `https://theanoma.company/work/${project.slug}` };
    return {
      content: [{ type: "text", text: JSON.stringify(payload, null, 2) }],
      structuredContent: { project: payload }
    };
  }
});

